-- CostingMethodHandler.RevaluatingAnotherRevaluationIsNotSupported: the revaluation in the way may be completed but not posted yet, so name its date, not its posting

UPDATE AD_Message SET MsgText='Für das Produkt {0} gibt es bereits eine spätere Kosten Neubewertung vom {1}. Eine Kosten Neubewertung kann nicht vor oder am selben Tag wie eine andere Neubewertung desselben Produkts beginnen. Bitte ein späteres Startdatum der Bewertung wählen, nach dem {1}.', Updated=TO_TIMESTAMP('2026-09-29 22:30:00','YYYY-MM-DD HH24:MI:SS'), UpdatedBy=100 WHERE AD_Message_ID=545879;
UPDATE AD_Message_Trl SET MsgText='Für das Produkt {0} gibt es bereits eine spätere Kosten Neubewertung vom {1}. Eine Kosten Neubewertung kann nicht vor oder am selben Tag wie eine andere Neubewertung desselben Produkts beginnen. Bitte ein späteres Startdatum der Bewertung wählen, nach dem {1}.', Updated=TO_TIMESTAMP('2026-09-29 22:30:01','YYYY-MM-DD HH24:MI:SS'), UpdatedBy=100 WHERE AD_Language IN ('de_DE','de_CH') AND AD_Message_ID=545879;
UPDATE AD_Message_Trl SET MsgText='Product {0} already has a later cost revaluation dated {1}. A cost revaluation cannot start before or on the same day as another revaluation of the same product. Please choose a later evaluation start date, after {1}.', Updated=TO_TIMESTAMP('2026-09-29 22:30:02','YYYY-MM-DD HH24:MI:SS'), UpdatedBy=100 WHERE AD_Language='en_US' AND AD_Message_ID=545879;
